"Create a team or recruit Trainees first.":"สร้างทีมหรือรับเด็กฝึกก่อน",
"The song list of a debuted or scheduled Stage is fixed. Create a new Stage to change songs (members, Centers, formations and costumes can still be adjusted).":"รายชื่อเพลงของสเตจที่เปิดตัวแล้วหรือมีกำหนดการแล้วจะถูกล็อก สร้างสเตจใหม่เพื่อเปลี่ยนเพลง (เมมเบอร์ เซ็นเตอร์ ฟอร์เมชัน และชุดยังปรับได้)",
