"That song is not available.":"เพลงนี้ใช้ไม่ได้",
"The Center must be one of the song's participating members.":"เซ็นเตอร์ต้องเป็นหนึ่งในเมมเบอร์ที่ร่วมแสดงเพลงนี้",
