"Rows reset to the standard layout for this number of members.":"รีเซ็ตแถวเป็นรูปแบบมาตรฐานสำหรับจำนวนเมมเบอร์นี้แล้ว",
"Ranking formation applied. You can still rearrange members manually.":"ใช้ฟอร์เมชันตามอันดับแล้ว ยังจัดเมมเบอร์เองต่อได้",
"That costume is not in the library.":"ชุดนั้นไม่อยู่ในคลัง",
"This song now follows the current version of the design.":"เพลงนี้ใช้ดีไซน์เวอร์ชันปัจจุบันแล้ว",
