"The new Stage must debut after the final performance of the current Stage (on a later date).":"สเตจใหม่ต้องเปิดตัวหลังรอบสุดท้ายของสเตจปัจจุบัน (ในวันถัดไป)",
"Transition cancelled.":"ยกเลิกการเปลี่ยนผ่านแล้ว",
"This Stage has not debuted yet.":"สเตจนี้ยังไม่เปิดตัว",
"Reusing a Stage keeps its number and history. Choose the dates below.":"การนำสเตจกลับมาใช้จะคงหมายเลขและประวัติไว้ เลือกวันด้านล่าง",
"Monthly price must be ¥100–¥20,000.":"ราคารายเดือนต้องอยู่ระหว่าง ¥100–¥20,000",
"At most 4 packages.":"มีแพ็กเกจได้สูงสุด 4 แบบ",
"Enter a theater name.":"ใส่ชื่อเธียเตอร์",
"No performers to arrange.":"ไม่มีผู้แสดงให้จัด",
"Choose the main and the secondary colour.":"เลือกสีหลักและสีรอง",
"Colours built from your main and secondary colours (each press gives a new combination). Save to keep them.":"สร้างชุดสีจากสีหลักและสีรองของคุณแล้ว (กดแต่ละครั้งได้คู่สีใหม่) กดบันทึกเพื่อเก็บไว้",
"Tap a colour of the costume first.":"แตะสีของชุดก่อน",
"Choose the new colour.":"เลือกสีใหม่",
"That colour is no longer used in this costume.":"ชุดนี้ไม่ได้ใช้สีนั้นแล้ว",
"Offer declined.":"ปฏิเสธข้อเสนอแล้ว",
"An adorable, cheerful and charming concept with playful expressions and sweet visuals.":"คอนเซ็ปต์น่ารักสดใสมีเสน่ห์ สีหน้าขี้เล่นกับภาพลักษณ์หวาน ๆ",
"Soft pastel colours, gentle smiles and a sugary, comforting atmosphere.":"สีพาสเทลนุ่มนวล รอยยิ้มอ่อนโยน และบรรยากาศหวานละมุนชวนอบอุ่นใจ",
"Candy Pop":"แคนดี้ป็อป",
"Lollipops, bright primary colours and a hyperactive sweet-shop world.":"อมยิ้ม สีสันสดจัด และโลกร้านขนมหวานที่ไม่เคยหยุดนิ่ง",
"Toy Box":"กล่องของเล่น",
"Members as living dolls and toys in a colourful, playful playroom.":"เมมเบอร์กลายเป็นตุ๊กตาและของเล่นมีชีวิต ในห้องเด็กเล่นสีสันสดใส",
"Pajama Party":"ปาร์ตี้ชุดนอน",
"A cosy sleepover with pillows, secrets and giggles late at night.":"ค้างคืนกับเพื่อนแสนอบอุ่น หมอน ความลับ และเสียงหัวเราะคิกคักยามดึก",
"Maid Café":"เมดคาเฟ่",
"Frilled aprons and devoted service with a wink, straight from Akihabara.":"ผ้ากันเปื้อนระบาย การบริการสุดใจพร้อมขยิบตา ตรงจากอากิฮาบาระ",
"Idol Classic":"ไอดอลคลาสสิก",
"The timeless idol image: ribbons, matching uniforms and bright smiles.":"ภาพลักษณ์ไอดอลที่ไม่มีวันเชย ริบบิ้น ชุดยูนิฟอร์มเข้าชุด และรอยยิ้มสดใส",
"Non-stop positivity and big gestures that make everyone smile.":"คิดบวกไม่หยุด กับท่าทางยิ่งใหญ่ที่ทำให้ทุกคนยิ้มได้",
"A pure and youthful concept that expresses sincerity, freshness and simplicity.":"คอนเซ็ปต์ใสบริสุทธิ์วัยแรกรุ่น ถ่ายทอดความจริงใจ ความสดชื่น และความเรียบง่าย",
"The sparkle of being young: running, laughing and believing in tomorrow.":"ประกายของวัยเยาว์ วิ่ง หัวเราะ และเชื่อมั่นในวันพรุ่งนี้",
"Classrooms, uniforms and after-school moments shared with friends.":"ห้องเรียน ชุดนักเรียน และช่วงเวลาหลังเลิกเรียนที่ได้ใช้ร่วมกับเพื่อน ๆ",
"The shy excitement of liking someone for the very first time.":"ความตื่นเต้นเขิน ๆ ของการแอบชอบใครสักคนเป็นครั้งแรก",
"Diary":"ไดอารี่",
"Private thoughts and small daily feelings, as if reading a girl's notebook.":"ความคิดส่วนตัวและความรู้สึกเล็ก ๆ ในแต่ละวัน เหมือนได้แอบอ่านสมุดบันทึกของเด็กสาว",
"Flower Language":"ภาษาดอกไม้",
"Blossoms and bouquets used to say what words cannot.":"ดอกไม้และช่อดอกไม้ที่บอกสิ่งที่คำพูดบอกไม่ได้",
"Butterfly":"ผีเสื้อ",
"Delicate transformation and lightness, like wings opening for the first time.":"การเปลี่ยนแปลงอันบอบบางและความเบาสบาย เหมือนปีกที่กางออกเป็นครั้งแรก",
"Soft lights, longing glances and the warmth of being in love.":"แสงไฟนุ่ม ๆ สายตาที่โหยหา และความอบอุ่นของการตกหลุมรัก",
"Valentine":"วาเลนไทน์",
"Chocolate, hand-written notes and the courage to confess.":"ช็อกโกแลต การ์ดเขียนด้วยลายมือ และความกล้าที่จะสารภาพรัก",
"Wedding":"งานแต่งงาน",
"White dresses, vows and the promise of a shared future.":"ชุดสีขาว คำสัญญา และอนาคตที่จะได้ใช้ร่วมกัน",
"Moonlight":"แสงจันทร์",
"A quiet night scene bathed in silver light and gentle longing.":"ค่ำคืนเงียบสงบที่อาบไล้ด้วยแสงเงิน และความคิดถึงอันอ่อนโยน",
"Starry Night":"ค่ำคืนพร่างดาว",
"A sky full of stars and wishes made side by side.":"ท้องฟ้าเต็มไปด้วยดวงดาว กับคำอธิษฐานที่ได้ขอเคียงข้างกัน",
"Secret Garden":"สวนลับ",
"A hidden place of flowers where private feelings are allowed to bloom.":"ดินแดนดอกไม้ลับตา ที่ความรู้สึกในใจได้รับอนุญาตให้เบ่งบาน",
"A confident and stylish concept featuring strong attitudes and sophisticated visuals.":"คอนเซ็ปต์มั่นใจมีสไตล์ ทัศนคติหนักแน่นกับภาพลักษณ์สุดเนี้ยบ",
