"A mysterious and dramatic concept with darker visuals and intense expressions.":"คอนเซ็ปต์ลึกลับดราม่า ภาพลักษณ์โทนมืดกับสีหน้าเข้มข้น",
"Black lace, candlelight and old-world melancholy.":"ลูกไม้สีดำ แสงเทียน และความเศร้าแบบโลกเก่า",
